## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/laacLogic.ts`

```typescript
// Left Atrial Appendage Closure (LAAC) — Watchman/Amulet Clinical Decision Logic
// Based on: ACC/AHA/HRS 2023 AF Guidelines, PROTECT AF, PREVAIL, CHAMPION-AF trials
// Reference: Joglar JA, et al. J Am Coll Cardiol. 2024;83(1):109-279. PMID: 38033089
// PROTECT AF: Holmes DR, et al. Lancet. 2009;374(9689):534-542. PMID: 19683639
// PREVAIL: Holmes DR, et al. J Am Coll Cardiol. 2014;64(1):1-12. PMID: 24998121

export interface LAACInput {
  // Patient demographics
  age: number;
  sex: 'male' | 'female';

  // AF type
  afType: 'paroxysmal' | 'persistent' | 'longstanding-persistent' | 'permanent';

  // CHA2DS2-VASc components
  chf: boolean;
  hypertension: boolean;
  age75orOlder: boolean;
  diabetes: boolean;
  stroke: boolean; // prior stroke/TIA/thromboembolism
  vascularDisease: boolean;
  age65to74: boolean;

  // Bleeding risk — HAS-BLED components
  uncontrolledHypertension: boolean;
  renalDisease: boolean;
  liverDisease: boolean;
  priorStrokeHistory: boolean;
  priorMajorBleeding: boolean;
  labileINR: boolean; // if on warfarin
  elderlyAge65: boolean;
  drugsAlcohol: boolean; // antiplatelet drugs or alcohol

  // Anticoagulation contraindications / intolerance
  acContradicated: boolean; // absolute contraindication to OAC
  acIntolerant: boolean; // intolerant to OAC (falls, compliance, preference)
  acFailed: boolean; // stroke on therapeutic OAC
  acHighRisk: boolean; // high bleeding risk on OAC

  // Specific bleeding history
  intracranialHemorrhage: boolean;
  gi_bleeding: boolean;
  fallRisk: boolean;

  // Anatomy
  laaSizeOstium: number; // LAA ostium diameter in mm (17–31 mm for Watchman FLX)
  laaMorphology: 'chicken-wing' | 'windsock' | 'cactus' | 'cauliflower' | 'unknown';
  laaThrombus: boolean;

  // Comorbidities
  ckdStage: 0 | 1 | 2 | 3 | 4 | 5;
  esrd: boolean; // end-stage renal disease on dialysis
  priorCardiacSurgery: boolean;
  pericardialDisease: boolean;
  atrialSeptalAneurysm: boolean;
  pfo: boolean;
}

export interface LAACResult {
  candidacyScore: number;
  cha2ds2vascScore: number;
  hasbledScore: number;
  recommendation: 'Appropriate' | 'Reasonable' | 'Consider with Caution' | 'Not Recommended';
  guidelineClass: string;
  deviceConsideration: string;
  keyFindings: string[];
  warnings: string[];
  references: string[];
}

function calcCHA2DS2VASc(input: LAACInput): number {
  let score = 0;
  if (input.chf) score += 1;
  if (input.hypertension) score += 1;
  if (input.age75orOlder) score += 2;
  if (input.diabetes) score += 1;
  if (input.stroke) score += 2;
  if (input.vascularDisease) score += 1;
  if (input.age65to74) score += 1;
  if (input.sex === 'female') score += 1;
  return score;
}

function calcHASBLED(input: LAACInput): number {
  let score = 0;
  if (input.uncontrolledHypertension) score += 1;
  if (input.renalDisease) score += 1;
  if (input.liverDisease) score += 1;
  if (input.priorStrokeHistory) score += 1;
  if (input.priorMajorBleeding) score += 1;
  if (input.labileINR) score += 1;
  if (input.elderlyAge65) score += 1;
  if (input.drugsAlcohol) score += 1;
  return Math.min(score, 9);
}

export function calculateLAACScore(input: LAACInput): LAACResult {
  const warnings: string[] = [];
  const keyFindings: string[] = [];
  let score = 0;

  const cha2ds2vascScore = calcCHA2DS2VASc(input);
  const hasbledScore = calcHASBLED(input);

  // Absolute contraindication
  if (input.laaThrombus) {
    warnings.push('CONTRAINDICATION: LAA thrombus present — LAAC contraindicated; anticoagulate and reassess in 6 weeks');
    return {
      candidacyScore: 0,
      cha2ds2vascScore,
      hasbledScore,
      recommendation: 'Not Recommended',
      guidelineClass: 'Class III: Harm',
      deviceConsideration: 'Defer until thrombus resolves',
      keyFindings,
      warnings,
      references: [],
    };
  }

  if (input.pericardialDisease) {
    warnings.push('Pericardial disease — increased pericardial effusion/tamponade risk; evaluate carefully');
  }

  // Stroke risk — must be high enough to justify procedure
  if (cha2ds2vascScore >= 4) {
    score += 30;
    keyFindings.push(`High stroke risk: CHA₂DS₂-VASc ${cha2ds2vascScore} — strong indication for stroke prevention`);
  } else if (cha2ds2vascScore >= 2) {
    score += 20;
    keyFindings.push(`Moderate stroke risk: CHA₂DS₂-VASc ${cha2ds2vascScore} — anticoagulation or LAAC indicated`);
  } else {
    warnings.push(`Low stroke risk: CHA₂DS₂-VASc ${cha2ds2vascScore} — LAAC benefit may not outweigh procedural risk`);
    score -= 10;
  }

  // OAC contraindication/intolerance — primary indication for LAAC
  if (input.acContradicated) {
    score += 30;
    keyFindings.push('Absolute contraindication to oral anticoagulation — LAAC is primary stroke prevention strategy');
  } else if (input.intracranialHemorrhage) {
    score += 25;
    keyFindings.push('Prior intracranial hemorrhage — LAAC preferred over OAC for stroke prevention (Class IIa)');
  } else if (input.acFailed) {
    score += 20;
    keyFindings.push('Stroke/TIA on therapeutic anticoagulation — LAAC reasonable as adjunct or alternative');
  } else if (input.acIntolerant || input.acHighRisk) {
    score += 15;
    keyFindings.push('OAC intolerance or high bleeding risk — LAAC is reasonable alternative (Class IIa)');
  } else {
    keyFindings.push('No OAC contraindication identified — LAAC vs OAC decision requires shared decision-making');
    score += 5;
  }

  // Bleeding risk
  if (hasbledScore >= 3) {
    score += 10;
    keyFindings.push(`High bleeding risk: HAS-BLED ${hasbledScore} — LAAC may reduce long-term bleeding vs OAC`);
  }

  if (input.gi_bleeding) {
    score += 10;
    keyFindings.push('Prior GI bleeding — LAAC reduces need for long-term anticoagulation');
  }

  if (input.fallRisk) {
    score += 5;
    keyFindings.push('High fall risk — LAAC reduces intracranial hemorrhage risk vs OAC');
  }

  // LAA anatomy
  if (input.laaSizeOstium >= 17 && input.laaSizeOstium <= 31) {
    keyFindings.push(`LAA ostium ${input.laaSizeOstium} mm — within Watchman FLX sizing range (17–31 mm)`);
    score += 10;
  } else if (input.laaSizeOstium > 31) {
    warnings.push(`LAA ostium ${input.laaSizeOstium} mm — exceeds Watchman FLX range; consider Amulet (up to 34 mm) or surgical ligation`);
    score -= 5;
  } else if (input.laaSizeOstium < 17 && input.laaSizeOstium > 0) {
    warnings.push(`LAA ostium ${input.laaSizeOstium} mm — below minimum device size; verify with 3D TEE`);
    score -= 5;
  }

  if (input.laaMorphology === 'cauliflower') {
    warnings.push('Cauliflower LAA morphology — higher thrombus risk and more complex implantation; experienced operator recommended');
  } else if (input.laaMorphology === 'chicken-wing') {
    keyFindings.push('Chicken-wing LAA morphology — may require specific device positioning; pre-procedure CT planning recommended');
  }

  // ESRD
  if (input.esrd) {
    warnings.push('ESRD on dialysis — contrast use limited; TEE guidance preferred; higher procedural risk');
    score -= 5;
  }

  // CKD
  if (input.ckdStage >= 4) {
    warnings.push('Advanced CKD — contrast nephropathy risk; consider TEE-only guidance');
  }

  score = Math.max(0, Math.min(100, score));

  let recommendation: LAACResult['recommendation'];
  let guidelineClass: string;
  let deviceConsideration: string;

  if (score >= 60) {
    recommendation = 'Appropriate';
    guidelineClass = 'Class IIa: LAAC is reasonable for patients with AF and high stroke risk who have contraindications to long-term OAC';
    deviceConsideration = 'Watchman FLX (17–31 mm) or Amulet device; pre-procedure CT angiography and TEE sizing required; 45-day TEE follow-up to confirm seal';
  } else if (score >= 40) {
    recommendation = 'Reasonable';
    guidelineClass = 'Class IIb: LAAC may be considered after thorough risk-benefit discussion';
    deviceConsideration = 'Multidisciplinary discussion with electrophysiology and structural heart team; confirm OAC alternatives exhausted';
  } else if (score >= 20) {
    recommendation = 'Consider with Caution';
    guidelineClass = 'Individualized decision — limited evidence in this clinical scenario';
    deviceConsideration = 'Optimize modifiable risk factors; reassess OAC candidacy; consider EP consultation';
  } else {
    recommendation = 'Not Recommended';
    guidelineClass = 'Class III: LAAC not recommended — insufficient stroke risk or OAC is safe and effective';
    deviceConsideration = 'Continue optimal anticoagulation therapy; reassess annually';
  }

  return {
    candidacyScore: score,
    cha2ds2vascScore,
    hasbledScore,
    recommendation,
    guidelineClass,
    deviceConsideration,
    keyFindings,
    warnings,
    references: [
      'Joglar JA, et al. 2023 ACC/AHA/ACCP/HRS Guideline for AF. J Am Coll Cardiol. 2024;83(1):109-279. PMID: 38033089',
      'Holmes DR, et al. PROTECT AF Trial. Percutaneous Closure of LAA vs Warfarin. Lancet. 2009;374(9689):534-542. PMID: 19683639',
      'Holmes DR, et al. PREVAIL Trial. Prospective Randomized Evaluation of the Watchman LAA Closure Device. J Am Coll Cardiol. 2014;64(1):1-12. PMID: 24998121',
      'Osmancik P, et al. PRAGUE-17 Trial. Left Atrial Appendage Closure vs Novel Anticoagulants. J Am Coll Cardiol. 2020;75(25):3122-3135. PMID: 32586591',
      'Lakkireddy D, et al. Amulet IDE Trial. Amulet vs Watchman for LAAC. JAMA. 2021;327(23):2295-2305. PMID: 34928388',
    ],
  };
}
